import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

/// Async-condition waitForIt: polls a future predicate until true.
Future<void> waitForTrue(Future<bool> Function() condition) async {
  for (var i = 0; i < 5000; i++) {
    if (await condition()) return;
    await Future<void>.delayed(const Duration(milliseconds: 5));
  }
  fail('timed out waiting: async condition');
}

/// The idle inbox-wake lanes (gh-1180): scheduled self-mail must be exempt
/// from the agent-chatter wake cap, foreign chatter must stay capped, and
/// every refused wake must leave a visible receipt.
///
/// `run()` creates the session at boot WITHOUT starting a turn — the
/// first stream call is the first wake — so the post-boot baseline is
/// zero calls.
void main() {
  late MemoryExecutionEnv env;
  late FakeCliIO io;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    io = FakeCliIO();
  });

  tearDown(() => io.close());

  AgentCli buildCli(FakeStreamFunction fake) => AgentCli(
    config: AgentCliConfig(
      model: testModel,
      apiKey: '[REDACTED:Sensitive Value]',
      env: env,
      sessionRoot: '/sessions',
      providerKind: 'openai-completions',
    ),
    io: io,
    streamFunction: fake.call,
  );

  /// Waits for the session to exist; returns (sessionId, 0 calls).
  Future<(String, int)> boot(FakeStreamFunction fake, AgentCli cli) async {
    final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    await waitForTrue(() async => (await repo.list(cwd: '/work')).isNotEmpty);
    return ((await repo.list(cwd: '/work')).first.id, fake.calls);
  }

  /// Sends one message shaped exactly like the scheduler's delivery of a
  /// self-addressed record: `[scheduled] ` prefix, from == to == own
  /// mailbox (what `_deliverDueInner` produces).
  Future<String> sendScheduledSelfMail(String id, String text) async {
    final mailbox = '$id/main';
    final message = AgentMessage(
      id: newMessageId(),
      fromId: mailbox,
      toId: mailbox,
      text: '[scheduled] $text',
      sentAt: DateTime.now().toUtc().toIso8601String(),
    );
    await FileMessagingRepository(
      env: env,
      root: '/sessions/--work--/messages',
    ).send(message);
    return message.id;
  }

  Future<void> sendForeignMail(String id, String text) async {
    await FileMessagingRepository(
      env: env,
      root: '/sessions/--work--/messages',
    ).send(
      AgentMessage(
        id: newMessageId(),
        fromId: 'peer-session/main',
        toId: '$id/main',
        text: text,
        sentAt: DateTime.now().toUtc().toIso8601String(),
      ),
    );
  }

  Future<List<Map<String, dynamic>>> receipts() async {
    final text = (await env.readTextFile(
      '/sessions/--work--/messages/_scheduled/receipts.jsonl',
    )).valueOrNull;
    if (text == null || text.isEmpty) return const [];
    return [
      for (final line in text.trim().split('\n'))
        jsonDecode(line) as Map<String, dynamic>,
    ];
  }

  test(
    'gh-1180 AC1: scheduled self-mail wakes the CLI even with the chatter '
    'streak capped, and the exempt wake never counts against the cap',
    () async {
      final fake = FakeStreamFunction([
        textTurn('on watch'),
        textTurn('still on watch'),
      ]);
      final cli = buildCli(fake);
      final run = cli.run();
      final (id, baseline) = await boot(fake, cli);
      // Ten agent-to-agent wakes already burned (the attach-driven REG
      // tests use the same seam): a pure self-scheduled chain has no
      // user-kind input to reset the streak, so pre-fix the gate refuses.
      cli.inboxWakeStreakForTest = 10;

      await sendScheduledSelfMail(id, 'night-watch sweep');

      await waitForTrue(
        () async => fake.calls == baseline + 1 && !cli.isBusy,
      ); // RED pre-fix: the watcher never wakes.
      expect(
        cli.inboxWakeStreakForTest,
        10,
        reason: 'the exempt lane must not count against the chatter cap',
      );

      io.sendLine('/exit');
      await run;
    },
    timeout: const Timeout(Duration(seconds: 60)),
  );

  test('gh-1180 AC4: a scheduled-self wake leaves a persisted receipt trail '
      '(wake_attempted + turn_started, correlated by message id)', () async {
    final fake = FakeStreamFunction([textTurn('on watch'), textTurn('ok')]);
    final cli = buildCli(fake);
    final run = cli.run();
    final (id, baseline) = await boot(fake, cli);
    cli.inboxWakeStreakForTest = 10;
    final mailId = await sendScheduledSelfMail(id, 'night-watch sweep');

    await waitForTrue(() async => fake.calls == baseline + 1 && !cli.isBusy);
    final trail = await receipts();
    final attempted = trail.where(
      (event) => event['event'] == 'wake_attempted',
    );
    expect(attempted, isNotEmpty);
    expect(
      (attempted.first['ids'] as List).cast<String>(),
      contains(mailId),
      reason: 'the receipt names the scheduled mail that prompted the wake',
    );
    expect(
      trail.where((event) => event['event'] == 'turn_started'),
      isNotEmpty,
    );

    io.sendLine('/exit');
    await run;
  }, timeout: const Timeout(Duration(seconds: 60)));

  test(
    'gh-1180 AC2 REG: foreign agent chatter stays capped — no wake past '
    'the streak cap, and the refusal is receipted once, not every tick',
    () async {
      final fake = FakeStreamFunction([textTurn('unused')]);
      final cli = buildCli(fake);
      final run = cli.run();
      final (id, baseline) = await boot(fake, cli);
      cli.inboxWakeStreakForTest = 10;

      await sendForeignMail(id, 'ping from a peer agent');
      // The watcher ticks every 2s; wait out three ticks of refusal.
      await Future<void>.delayed(const Duration(seconds: 6));
      expect(
        fake.calls,
        baseline,
        reason: 'anti-storm REG: capped chatter must not wake the agent',
      );
      expect(
        io.out.toString().contains('wake refused'),
        isTrue,
        reason: 'a refused wake is visible, not silent',
      );
      final refused = (await receipts()).where(
        (event) => event['event'] == 'wake_refused',
      );
      expect(refused, hasLength(1), reason: 'one receipt per refusal episode');

      io.sendLine('/exit');
      await run;
    },
    timeout: const Timeout(Duration(seconds: 60)),
  );
}

Now let me read the policy test, and check where the streak reset happens on user input in the CLI (`_beginUserPrompt`, etc.) — and how `resetStreak` is called. The thread 2 fix: fold the "announced" latch into `InboxWakePolicy` next to the streak so the two cannot drift apart. That's the cleaner option: the policy's `resetStreak()` clears the announced flag too, and the CLI's refusal path asks the policy. Also the wake-refused receipt should be unconditional per refusal episode... wait, no. Let me re-read thread 2:

1. The `wake_refused` receipt is inside the `!_inboxWakeRefusalAnnounced` guard — written once per flag lifetime, not once per refusal episode. Fix: move the `wake_refused` append out of the `if` — unconditional per refusal tick? Hmm, but that conflicts with thread 1 (per-tick spam). Actually thread 1 says dedupe `wake_attempted` per episode; thread 2 says `wake_refused` should be per-episode too (not per-flag-lifetime). So the right design: gate both receipts on "episode" — i.e., a new refusal episode (after a reset/wake) emits one `wake_attempted` + one `wake_refused`; while the gate continues to hold on subsequent ticks, no repeated receipts (or dedupe by state change: lane/ids change).

Let me think about what "episode" means:
- A refusal episode starts when a wake is refused after a state where the previous decision was not a refusal (i.e., the announced flag is false).
- While the same refusal persists across 2s ticks (same pending batch), no new receipts, no new dim line.
- When user input resets the streak (flag cleared), a subsequent refusal is a NEW episode → one receipt + one dim line.
- When a successful wake happens, flag cleared → subsequent refusal is a new episode.

Thread 2 also asks: "the field's documented reset path does not exist" — clear `_inboxWakeRefusalAnnounced` wherever the streak is reset on user input (or fold the latch into `InboxWakePolicy` next to the streak so the two cannot drift apart). The better fix per the reviewer: fold the "announced" latch into `InboxWakePolicy`. So `InboxWakePolicy` gets a method like `markRefusalAnnounced()` / the reset clears it. Let me design:

In `InboxWakePolicy`:
```dart
bool _refusalAnnounced = false;

/// Whether the current refusal episode has already been announced by the
/// host (dim line + receipt). ...
bool get refusalAnnounced => _refusalAnnounced;

void markRefusalAnnounced() => _refusalAnnounced = true;

void resetStreak() {
  streak = 0;
  _refusalAnnounced = false;
}
```

And in the successful non-scheduledSelf wake path: `_inboxWakePolicy.clearRefusalEpisode()` — wait, the CLI currently clears `_inboxWakeRefusalAnnounced = false` when `decision.lane != InboxWakeLane.scheduledSelf`. With the latch folded into the policy, the policy itself can clear the latch on any decision that wakes in a non-scheduledSelf lane... Hmm, but the policy methods are: `wakeDecisionFor` books the wake. Actually cleaner: the policy clears `_refusalAnnounced` inside `wakeDecisionFor` whenever a wake is allowed and the lane is not `scheduledSelf` (mirroring the current CLI behavior), and `resetStreak()` clears it too. Then the CLI asks `policy.refusalAnnounced` to decide whether to print/receipt, and calls `policy.markRefusalAnnounced()` after printing.

Wait — but per thread 2 point 1, the `wake_refused` receipt should be UNCONDITIONAL (per attempt?) — no wait, re-read: "AC4 wants every wake attempt accounted for ("or wake-refused + reason"); the receipt should be unconditional and only the terminal line gated."

Hmm, so thread 2 says: receipt `wake_refused` on every refusal (unconditional), gate only the terminal dim line. But thread 1 says dedupe `wake_attempted` per episode. These two together: thread 1 says per-tick `wake_attempted` rows are noise — "receipt one `wake_attempted` per episode/state change (same gate as the refusal line), or only when the pending-batch ids actually change."

So the review's two asks:
- Thread 1: `wake_attempted` NOT per tick — per episode/state change.
- Thread 2: `wake_refused` NOT once per flag lifetime — per episode (unconditional relative to the announce guard; the guard should cover only the terminal line).

If both are gated per-episode, then during a sustained refusal: 1 `wake_attempted` + 1 `wake_refused`, then silence. That satisfies both: thread 1 (no per-tick spam) and thread 2 (receipt per episode, not per flag lifetime — a new episode after user input re-receipts).

Alternatively `wake_refused` per tick but `wake_attempted` per episode? That contradicts thread 1's "The signal lines drown in repeated `wake_attempted` rows" — the refusal receipts would equally drown the trail. The cleanest interpretation consistent with both threads: one `wake_attempted` + one `wake_refused` per refusal episode; terminal dim line once per episode; new episode begins after a streak reset (user input) or a successful wake.

Hmm wait, but also thread 1 offers "or only when the pending-batch ids actually change". The episode-based approach is simpler and consistent. Let me design:

In `InboxWakePolicy`:
```dart
/// One visible refusal per episode: the gate holds until user input
/// arrives or a wake succeeds, so announcing on every watcher tick would
/// spam the terminal and the receipt trail. A new episode opens when the
/// streak resets (user input) or a non-exempt wake succeeds.
bool _refusalAnnounced = false;

/// Whether the current refusal episode has been announced (dim line +
/// receipt) by the host yet.
bool get refusalAnnounced => _refusalAnnounced;

/// The host marks the current refusal episode announced after printing
/// the terminal line and persisting the receipt.
void markRefusalAnnounced() => _refusalAnnounced = true;

/// A delivered user-kind message (or a typed line) IS the user talking.
/// Also closes any open refusal episode: the next refusal must be
/// announced (and receipted) again.
void resetStreak() {
  streak = 0;
  _refusalAnnounced = false;
}
```

And in `wakeDecisionFor`, for allowed non-scheduledSelf wakes: `_refusalAnnounced = false;` (clears the episode on a successful chatter/user wake — mirroring the old CLI behavior "cleared by any successful non-exempt wake").

