  /// Serializes the async file work; errors are swallowed (best effort).
  static void _enqueue(Future<void> Function() work) {
    _writes = _writes.then((_) async {
      try {
        await work();
      } on Object {
        // Best effort — logging must never break the app.
      }
    });
